import { Client } from 'minio';
import type { Readable } from 'node:stream';

export interface MinioResourceStorageOptions {
  endpoint: string;
  port: number;
  useSSL?: boolean;
  accessKey: string;
  secretKey: string;
  quarantineBucket?: string;
  readyBucket?: string;
}

/** Private MinIO storage. Object keys are generated by application services, never received from clients. */
export class MinioResourceStorage {
  private readonly client: Client;
  private readonly quarantineBucket: string;
  private readonly readyBucket: string;
  private initialization?: Promise<void>;

  constructor(options: MinioResourceStorageOptions) {
    this.client = new Client({ endPoint: options.endpoint, port: options.port, useSSL: options.useSSL ?? false, accessKey: options.accessKey, secretKey: options.secretKey });
    this.quarantineBucket = options.quarantineBucket ?? 'smartpath-quarantine';
    this.readyBucket = options.readyBucket ?? 'smartpath-resources';
  }

  async putQuarantine(objectKey: string, bytes: Buffer, mimeType: string): Promise<void> {
    await this.ensureBuckets();
    await this.client.putObject(this.quarantineBucket, objectKey, bytes, bytes.length, { 'Content-Type': mimeType });
  }

  async deleteQuarantine(objectKey: string): Promise<void> {
    await this.ensureBuckets();
    await this.client.removeObject(this.quarantineBucket, objectKey);
  }

  async getQuarantineStream(objectKey: string): Promise<Readable> {
    await this.ensureBuckets();
    return this.client.getObject(this.quarantineBucket, objectKey);
  }

  async promote(quarantineObjectKey: string, readyObjectKey: string): Promise<void> {
    await this.ensureBuckets();
    await this.client.copyObject(this.readyBucket, readyObjectKey, `/${this.quarantineBucket}/${quarantineObjectKey}`);
  }

  async signedReadyDownload(objectKey: string, expiresSeconds = 300): Promise<string> {
    await this.ensureBuckets();
    return this.client.presignedGetObject(this.readyBucket, objectKey, expiresSeconds);
  }

  async getReadyStream(objectKey: string): Promise<Readable> {
    await this.ensureBuckets();
    return this.client.getObject(this.readyBucket, objectKey);
  }

  async putPrivate(objectKey: string, bytes: Buffer, mimeType: string): Promise<void> {
    await this.ensureBuckets();
    await this.client.putObject(this.readyBucket, objectKey, bytes, bytes.length, { 'Content-Type': mimeType });
  }

  private async ensureBuckets(): Promise<void> {
    this.initialization ??= this.createBuckets();
    return this.initialization;
  }

  private async createBuckets(): Promise<void> {
    for (const bucket of [this.quarantineBucket, this.readyBucket]) {
      if (!await this.client.bucketExists(bucket)) await this.client.makeBucket(bucket, 'us-east-1');
    }
  }
}
